def profit(legs, s_t):
    total = 0.0
    for kind, side, strike, premium in legs:
        if kind == 'call':
            pay = max(s_t - strike, 0)
        else:
            pay = max(strike - s_t, 0)
        if side == 'long':
            total += pay - premium
        else:
            total += premium - pay
    return total
